#include <algorithm>
#include <cmath>

#include <danikk_space_engine/profiler.h>
#include <danikk_space_engine/config.h>
#include <danikk_space_engine/systems/planet/planet.h>
#include <danikk_space_engine/world.h>

namespace danikk_space_engine
{
	namespace
	{
		constexpr double chunk_update_distance = planet_voxel_size * 2.0;
	}

	/**
	 * @brief Stamps pending mesh requests with current component identity for the shared generator.
	 * @param planet Planet state holding requests generated by the latest desired-set update.
	 * @param world World whose worker queue receives the replacement request set.
	 * @param slot Component slot supplying body ID, slot ID, and generation ID for result validation.
	 */
	void PlanetSystem::queuePlanetRequests(PlanetData& planet)
	{
		/**
		 * @brief Measures the duration of the enclosing profiler scope.
		 */
		DSE_WATCH();
		for(ChunkMeshGenerationRequest& request : planet.pending_requests)
		{
			request.world_body_id = planet.world_body_id;
			request.planet_generation_id = planet.generation_id;
		}
		world.chunk_mesh_generation.replacePlanetRequests(
			planet.world_body_id, planet.generation_id, planet.pending_requests);
	}

	/**
	 * @brief Destroys loaded chunks outside the current desired set and removes their lookup records.
	 * @param planet Lookup containing the current desired set and loaded chunk IDs.
	 * @param world World that coordinates chunk, point, and mesh resources.
	 */
	void PlanetSystem::unloadChunksOutsideDesiredSet(PlanetData& planet)
	{
		/**
		 * @brief Measures the duration of the enclosing profiler scope.
		 */
		DSE_WATCH();
		for(size_t index = 0; index < planet.chunk_lookup.entries.size();)
		{
			const PlanetChunkLookupEntry& entry = planet.chunk_lookup.entries[index];
			if((!entry.has_record && entry.chunk_id == static_cast<ChunkId>(-1))
				|| planet.chunk_lookup.isDesired(entry.grid_coordinate))
			{
				++index;
				continue;
			}
			if(entry.chunk_id != static_cast<ChunkId>(-1) && world.chunks.isChunkActive(entry.chunk_id))
			{
				world.chunks.destroyChunk(entry.chunk_id);
			}
			planet.chunk_lookup.remove(entry.grid_coordinate);
		}
	}

	/**
	 * @brief Rebuilds desired chunk coordinates and queues only coordinates without generation records.
	 *
	 * Enumerates the camera-centered bounding cube, filters cells by closest-point distance to the
	 * load-radius sphere, snapshots planet parameters and terrain edits into requests, then unloads
	 * loaded chunks outside the new set and clears face references invalidated by that replacement.
	 * Coordinates with a completed empty result remain marked generated and are not queued again;
	 * pending requests carry the terrain revision and component incarnation used to validate results.
	 * @param planet Mutable lookup and chunk-set state for the planet.
	 * @param slot Planet component slot used to stamp requests with owner identity.
	 * @param world World used to unload chunks and clear controller selections.
	 * @param camera_position Camera position relative to the planet center.
	 */
	void PlanetSystem::updatePlanetChunks(PlanetData& planet, const glm::dvec3& camera_position)
	{
		/**
		 * @brief Measures the duration of the enclosing profiler scope.
		 */
		DSE_WATCH();
		planet.last_chunk_update_position = camera_position;
		planet.last_chunk_update_revision = planet.terrain_revision;
		planet.last_chunk_update_mesh_generator = settings.planet_mesh_generator;
		planet.chunk_set_initialized = true;
		planet.chunk_updates_active = true;
		if(planet.terrain_snapshot == nullptr
			|| planet.terrain_snapshot->world_body_id != planet.world_body_id
			|| planet.terrain_snapshot->planet_generation_id != planet.generation_id
			|| planet.terrain_snapshot->terrain_revision != planet.terrain_revision
			|| planet.terrain_snapshot->planet_radius != planet.radius
			|| planet.terrain_snapshot->core_radius != planet.core_radius
			|| planet.terrain_snapshot->noise_seed != planet.noise_seed)
		{
			std::shared_ptr<PlanetTerrainSnapshot> snapshot = std::make_shared<PlanetTerrainSnapshot>();
			snapshot->world_body_id = planet.world_body_id;
			snapshot->planet_generation_id = planet.generation_id;
			snapshot->terrain_revision = planet.terrain_revision;
			snapshot->planet_radius = planet.radius;
			snapshot->core_radius = planet.core_radius;
			snapshot->noise_seed = planet.noise_seed;
			snapshot->terrain_edits = planet.terrain_edits;
			planet.terrain_snapshot = static_cast<std::shared_ptr<const PlanetTerrainSnapshot>&&>(snapshot);
		}
		const double chunk_width = planet_chunk_width;
		const glm::dvec3 range(planet.chunk_load_radius);
		const glm::ivec3 minimum_key(
			static_cast<int>(std::floor((camera_position.x - range.x) / chunk_width)),
			static_cast<int>(std::floor((camera_position.y - range.y) / chunk_width)),
			static_cast<int>(std::floor((camera_position.z - range.z) / chunk_width)));
		const glm::ivec3 maximum_key(
			static_cast<int>(std::floor((camera_position.x + range.x) / chunk_width)),
			static_cast<int>(std::floor((camera_position.y + range.y) / chunk_width)),
			static_cast<int>(std::floor((camera_position.z + range.z) / chunk_width)));
		const double radius_squared = planet.chunk_load_radius * planet.chunk_load_radius;
		DynamicArray<ChunkMeshGenerationRequest> requests;
		planet.chunk_lookup.clearDesired();

		for(int z = minimum_key.z; z <= maximum_key.z; z++)
		{
			for(int y = minimum_key.y; y <= maximum_key.y; y++)
			{
				for(int x = minimum_key.x; x <= maximum_key.x; x++)
				{
					const glm::ivec3 key(x, y, z);
					const glm::dvec3 chunk_minimum = glm::dvec3(key) * chunk_width;
					const glm::dvec3 chunk_maximum = chunk_minimum + glm::dvec3(chunk_width);
					const glm::dvec3 closest = glm::clamp(camera_position, chunk_minimum, chunk_maximum);
					if(glm::dot(camera_position - closest, camera_position - closest) > radius_squared) continue;

					planet.chunk_lookup.markDesired(key);
					if(planet.chunk_lookup.isGenerated(key, settings.planet_mesh_generator)) continue;

					ChunkMeshGenerationRequest request;
					request.source = ChunkMeshSource::planet_terrain;
					request.world_body_id = planet.world_body_id;
					request.planet_generation_id = planet.generation_id;
					request.terrain_revision = planet.terrain_revision;
					request.chunk_width = chunk_width;
					request.voxel_size = planet_voxel_size;
					request.planet_mesh_generator = settings.planet_mesh_generator;
					request.grid_coordinate = key;
					request.chunk_position = chunk_minimum;
					request.planet_terrain = planet.terrain_snapshot;
					requests.push(request);
				}
			}
		}

		std::sort(requests.begin(), requests.end(), [&camera_position, chunk_width](
			const ChunkMeshGenerationRequest& left, const ChunkMeshGenerationRequest& right)
		{
			const glm::dvec3 left_center = left.chunk_position + glm::dvec3(chunk_width * 0.5);
			const glm::dvec3 right_center = right.chunk_position + glm::dvec3(chunk_width * 0.5);
			return glm::dot(left_center - camera_position, left_center - camera_position)
				< glm::dot(right_center - camera_position, right_center - camera_position);
		});

		planet.pending_requests = static_cast<DynamicArray<ChunkMeshGenerationRequest>&&>(requests);
		unloadChunksOutsideDesiredSet(planet);
	}

	/**
	 * @brief Destroys generated chunks intersecting a terrain-edit sphere plus a mesh-sampling margin.
	 * @param planet Planet lookup containing loaded grid coordinates.
	 * @param world World owning the affected chunk resources.
	 * @param center Edit center relative to the planet origin.
	 * @param radius Radius of the spherical edit stamp.
	 */
	void PlanetSystem::invalidateChunksAroundEdit(PlanetData& planet, const PlanetTerrainEdit& edit)
	{
		/**
		 * @brief Measures the duration of the enclosing profiler scope.
		 */
		DSE_WATCH();
		for(PlanetChunkLookupEntry& entry : planet.chunk_lookup.entries)
		{
			if(!entry.has_record) continue;
			const glm::dvec3 minimum = glm::dvec3(entry.grid_coordinate) * planet_chunk_width;
			const glm::dvec3 maximum = minimum + glm::dvec3(planet_chunk_width);
			const glm::dvec3 closest = glm::clamp(edit.center, minimum, maximum);
			const double invalidation_radius = edit.radius + planet_voxel_size * 2.0;
			if(glm::dot(edit.center - closest, edit.center - closest) > invalidation_radius * invalidation_radius)
			{
				continue;
			}
			if(entry.chunk_id != static_cast<ChunkId>(-1) && world.chunks.isChunkActive(entry.chunk_id))
			{
				entry.has_record = false;
			}
			else planet.chunk_lookup.remove(entry.grid_coordinate);
		}
	}
}
